-- Resolve existing duplicates first, and coordinate writes so duplicates cannot reappear.
CREATE UNIQUE INDEX CONCURRENTLY users_email_uq_idx
ON users (email);

SELECT indexrelid::regclass AS index_name, indisvalid, indisready
FROM pg_index
WHERE indexrelid = 'public.users_email_uq_idx'::regclass;

ALTER TABLE users
ADD CONSTRAINT users_email_key UNIQUE USING INDEX users_email_uq_idx;

-- Optional: pgstattuple may need to be installed by an administrator.
CREATE EXTENSION IF NOT EXISTS pgstattuple;

SELECT version, tree_level, index_size,
       avg_leaf_density, leaf_fragmentation,
       leaf_pages, deleted_pages
FROM pgstatindex('public.orders_status_created_at_idx');
